export async function startReviewStudioCommand(options?: StartReviewStudioOptions): Promise<void> {
  if (options?.serve) {
    const runtime = resolveReviewUiRuntimeContext({ port: options.port, preferDevUi: options.devUi });
    await runStudioServeProcess(runtime);
    return;
  }

  const runtime = resolveReviewUiRuntimeContext({ port: options?.port, preferDevUi: options?.devUi });
  if (options?.status) {
    const studioStatus = await getReviewStudioRuntimeStatus(runtime);
    if (studioStatus.running) {
      p.log.success(`Studio runtime is running at ${studioStatus.appUrl}`);
      if (studioStatus.runtime) {
        p.log.message(`PID: ${studioStatus.runtime.pid}`);
        p.log.message(`Started: ${studioStatus.runtime.startedAt}`);
      }
      return;
    }
    if (studioStatus.stale) {
      p.log.warning('Studio runtime metadata exists but runtime is not healthy.');
      return;
    }
    p.log.warning('Studio runtime is not running.');
    return;
  }

  if (options?.stop) {
    const stopped = await stopReviewStudioRuntime(runtime);
    if (stopped.stopped) {
      p.log.success('Stopped Studio runtime.');
      return;
    }
    if (stopped.stale) {
      p.log.warning('Studio runtime was stale. Cleared runtime metadata.');
      return;
    }
    p.log.warning('No running Studio runtime found for this repository.');
    return;
  }

  const routePath = options?.routePath ?? '/';
  const detach = options?.detach ?? Boolean(options?.routePath);
  if (!detach) {
    const appUrl = `http://127.0.0.1:${runtime.port}${routePath}`;
    const status = await getReviewStudioRuntimeStatus(runtime);
    if (status.running) {
      if (!status.runtime) {
        throw new Error(
          `Port ${runtime.port} is already in use by a non-Nimbus process. Use --port <n> or stop that process.`
        );
      }
      const stopped = await stopReviewStudioRuntime(runtime);
      if (!stopped.stopped) {
        if (stopped.stale) {
          throw new Error(
            `Could not stop existing Studio runtime on port ${runtime.port}. Runtime state is stale; run \`nimbus review studio --stop\` and retry.`
          );
        }
        throw new Error(
          `Could not stop existing Studio runtime on port ${runtime.port}. Please retry or use a different --port.`
        );
      }
      p.log.message('Stopped existing Studio runtime to start foreground session.');
    } else if (status.stale) {
      const cleared = await clearStaleReviewStudioRuntimeMetadata(runtime);
      if (cleared) {
        p.log.warning('Cleared stale Studio runtime metadata before foreground start.');
      }
    }

    openBrowser(appUrl);
    p.log.success(`Opened ${appUrl}`);
    await runStudioServeProcess(runtime);
    return;
  }

  const studio = await ensureReviewStudioRuntime(runtime, { routePath });
  openBrowser(studio.appUrl);
  p.log.success(`Opened ${studio.appUrl}`);
  p.log.message(studio.reused ? 'Reused existing Studio runtime.' : 'Started Studio runtime.');
}

